  // Inline: buildPromptParams
  var rulesContext = rules.length
    ? "\n        MANDATORY COLGATE RULES:\n        " +
      JSON.stringify(rules) +
      '\n        INSTRUCTION: Check each item against ONLY these specific rules above. If a rule matches, set "rule_applied" to the EXACT rule type name from the list: ' +
      JSON.stringify(rules.map(function (r) { return r.type; })) +
      '.\n        CRITICAL: Do NOT invent or fabricate rule names. If no rule from the above list applies, set "rule_applied" to "".\n        '
    : '\nIMPORTANT: No custom rules are active. Always set "rule_applied" to "" for every item.\n';
  var usageInstruction = showUsage
    ? '\n       - 🔵 **Usage & Ops**: Operational constraints (seats, API limits, pricing, renewals, auto-renew, notice periods). Identify ONLY constraints that restrict or negatively impact COLGATE. IGNORE restrictions placed solely on the counterparty. DO NOT flag rights/powers/privileges granted TO Colgate.\n         **CRITICAL**: For Usage items, include a "watchout" field explaining the operational danger AND "category" must be exactly "Usage".'
    : "";
  var usageCategoryAlt = showUsage ? ' | "Usage"' : "";
  var watchoutField = showUsage ? '"watchout": "Operational warning (Usage Only)",' : "";
  var promptParams = {
    rulesContext: rulesContext,
    usageInstruction: usageInstruction,
    usageCategoryAlt: usageCategoryAlt,
    watchoutField: watchoutField,
    text: text.substring(0, 500000),
  };

  // Resolve prompt — load template from IDB (prompts store, key
  // "legalRisksReview"), then substitute params via eli.ai.formatPrompt.
  // Kernel doesn't ship a `loadPrompt` wrapper; tools that need a named
  // template do the IDB get + formatPrompt pipeline inline (matches
  // CLAUDE.md "fix at upstream source, not kernel sprawl"). Prompt
  // bundle = data/prompts.json → __data_prompts data row.
  var ai = providers.ai || (window.eli && window.eli.ai);
  var storage = (providers.storage) || (window.eli && window.eli.storage);
  if (!ai || typeof ai.complete !== "function") {
