    return Promise.reject(new Error("eli.ai.formatPrompt missing"));
  }
  if (!storage || typeof storage.get !== "function") {
    return Promise.reject(new Error("eli.storage missing"));
  }
  var promptPromise = storage.get("prompts", "legalRisksReview").then(function (row) {
    var template = row && (row.text || row.template || row.body);
    if (!template) {
      throw new Error("legalRisksReview prompt missing — install AI Prompts data bundle (Settings → Check for Updates)");
    }
