  });

  return promptPromise.then(function (prompt) {
    if (!prompt) throw new Error("legalRisksReview prompt is empty");
    return ai.complete(prompt, { signal: input.signal, sanitize: false });
  }).then(function (raw) {
    // Inline: parseAiJson
    var data = null;
    if (raw) {
      var s = String(raw).trim().replace(/^```(?:json)?\s*/i, "").replace(/```$/, "").trim();
      try { data = JSON.parse(s); } catch (e) { /* fall through */ }
      if (!data) {
        var startObj = s.indexOf("{");
        var startArr = s.indexOf("[");
        var start = -1;
        if (startObj === -1) start = startArr;
        else if (startArr === -1) start = startObj;
        else start = Math.min(startObj, startArr);
        if (start !== -1) {
          var open = s[start];
          var close = open === "{" ? "}" : "]";
          var depth = 0, inStr = false, esc = false;
          for (var i = start; i < s.length; i++) {
            var c = s[i];
