    if (Array.isArray(out)) {
      out = { items: out };
    } else if (out && typeof out === "object" && !out.items) {
      var foundKey = Object.keys(out).filter(function (k) {
        return Array.isArray(out[k]);
      })[0];
      out.items = foundKey ? out[foundKey] : [];
    } else if (!out || typeof out !== "object") {
      out = { items: [] };
    }
    if (Array.isArray(out.items) && out.items.length) {
      out.items.forEach(function (item) {
        // Normalize the paragraph anchor — AI may return id under any
        // of these field names. Coerce to canonical "ELI_IDX_<n>" (the
        // kernel's shared structural-map prefix). If nothing anchor-
        // shaped is present, leave id null so LOCATE can fallback to
        // text search.
        var raw = item.id || item.paragraph_id || item.paragraphId ||
                  item.anchor || item.anchor_id || item.anchorId || "";
        raw = String(raw).trim().replace(/^_+/, ""); // strip stray leading `_`
        var normalized = "";
        if (raw.indexOf("ELI_IDX_") === 0) {
          normalized = raw;
        } else {
          var m = raw.match(/(\d+)$/);
          if (m) normalized = "ELI_IDX_" + m[1];
        }
        item.id = normalized || null;

        if (!item.category) item.category = "Risk";
        var cat = String(item.category).toLowerCase().trim();
        if (cat.indexOf("risk") !== -1 || cat.indexOf("liability") !== -1 || cat.indexOf("issue") !== -1) {
          item.category = "Risk";
        } else if (
          cat.indexOf("usage") !== -1 ||
          cat.indexOf("ops") !== -1 ||
          cat.indexOf("operational") !== -1 ||
          cat.indexOf("restriction") !== -1
        ) {
          item.category = "Usage";
        } else {
          item.category = "Risk";
        }
      });
      var ruleNames = rules.map(function (r) { return String(r.type || "").toLowerCase().trim(); });
      out.items.forEach(function (item) {
        if (!item.rule_applied) return;
        var applied = String(item.rule_applied).toLowerCase().trim();
        var valid = ruleNames.some(function (name) {
          return name && (applied.indexOf(name) !== -1 || name.indexOf(applied) !== -1);
        });
        if (!valid) item.rule_applied = "";
      });

      // 2026-05-13: enrich each item with structural-map section info.
      // For each `ELI_LR_<n>` id, derive the paragraph index and look
      // up the enclosing header so the parenthetical badge on the
      // results card can show the REAL section ("§ 4.5 Confidentiality")
      // and be clickable to jump there. Falls back gracefully when the
      // kernel doesn't expose readStructuralMap (legacy kernels) or
      // when the call fails — original `item.clause_ref` (AI-derived)
      // remains the fallback in the view.
      //
