      // don't pay the round-trip per item. Kernel caches the map by
      // docHash so this call is ~0ms when the map is fresh.
      try {
        var hostP = providers.host || (window.eli && window.eli.host);
        if (hostP && typeof hostP.readStructuralMap === "function") {
          return hostP.readStructuralMap({ prefix: "ELI_IDX_" }).then(function (smap) {
            try {
              var byParaIdx = (smap && smap.byParagraphIdx) || {};
              out.items.forEach(function (item) {
                if (!item || !item.id) return;
                var m = String(item.id).match(/_(\d+)$/);
                if (!m) return;
                var paraIdx = parseInt(m[1], 10);
                if (!isFinite(paraIdx)) return;
                var sec = (typeof smap.getSection === "function") ? smap.getSection(paraIdx) : null;
                // Walk backward to find the header ROW for the anchor.
                var headRow = null;
                var thisRow = byParaIdx[paraIdx];
                if (thisRow && thisRow.isHeader) {
                  headRow = thisRow;
                } else {
                  for (var pj = paraIdx - 1; pj >= 0; pj--) {
                    var c = byParaIdx[pj];
                    if (c && c.isHeader) { headRow = c; break; }
                  }
                }
                if (sec) {
                  item._sectionNumber = sec.number || "";
                  item._sectionTitle = sec.title || "";
                  if (headRow && headRow.anchor) item._sectionAnchor = headRow.anchor;
                } else {
                  // Pre-header paragraph — fall back to the kernel's
                  // belongsTo string ("Document Introduction" by default)
                  // so the view at least has a non-empty context tag.
                  var fallback = (thisRow && thisRow.belongsTo) || "Document Introduction";
                  item._sectionNumber = "";
                  item._sectionTitle = fallback;
                  item._sectionBelongsToOnly = true;
                }
              });
            } catch (enrichErr) {
              // Enrichment is purely decorative — never fail the analysis.
              try {
                if (window.eli && window.eli.log) {
                  window.eli.log.event("tool", "legal_risks_section_enrich_failed", {
                    msg: enrichErr && enrichErr.message,
                  });
                }
              } catch (_) {}
            }
            return out;
          }).catch(function () {
            // Kernel might not have readStructuralMap yet — silently
            // proceed without section enrichment. View falls back to
            // item.clause_ref for the parenthetical.
            return out;
          });
        }
      } catch (_) { /* tolerate */ }
    }
    var riskCount = (out.items || []).filter(function (i) { return i.category === "Risk"; }).length;
    var usageCount = (out.items || []).length - riskCount;
    out._rulesWereActive = rules.length > 0;
    out._rulesUsed = rules.map(function (r) { return r.type; });
    return {
      items: out.items || [],
      overview: out.overview || "Analysis complete.",
      balance_analysis: out.balance_analysis || "",
      raw: out,
      rulesActive: rules.length > 0,
      riskCount: riskCount,
      usageCount: usageCount,
      provenance: {
        kernelVersion: (window.eli && window.eli.kernelVersion) || "v3",
        toolVersion: "v3.0",
        docHash: docHash,
        timestamp: Date.now(),
      },
    };
  });
}

