  // ─── Section renderer (collapsible) ──────────────────────────────
  function _renderSection(sectionKey, title, icon, color, contentHtml, count, defaultCollapsed) {
    var bodyId = "_eli3_lr_section_body_" + sectionKey;
    var arrowId = "_eli3_lr_section_arrow_" + sectionKey;
    var collapsed = !!defaultCollapsed;
    return '<div class="_eli3_lr_results_section_wrap _eli3_lr_section_' + sectionKey + '">' +
      '<div class="_eli3_lr_results_section_head" data-toggle="section-' + sectionKey + '" style="background:' + color + ';">' +
        '<span class="_eli3_lr_results_section_icon">' + icon + '</span>' +
        '<div class="_eli3_lr_results_section_title">' + title + '</div>' +
        '<div class="_eli3_lr_results_section_count">' + count + '</div>' +
        '<span class="_eli3_lr_results_section_arrow" id="' + arrowId + '">' + (collapsed ? "◀" : "▼") + '</span>' +
      '</div>' +
