  }

  // ─── Section 1: Legal Risks ──────────────────────────────────────
  var risksContent = risks.length
    ? risks.map(function (it) { return _renderItemCard(it, items.indexOf(it)); }).join("")
    : '<div class="_eli3_lr_results_empty"><div class="_eli3_lr_results_empty_icon">✅</div><div class="_eli3_lr_results_empty_desc">No legal risks detected.</div></div>';
  var risksSectionHtml = _renderSection("risks", "Legal Risks", "🔴", "#c62828", risksContent, risks.length, false);

  // ─── Section 2: Usage Risks ──────────────────────────────────────
  var usageSectionHtml = "";
  if (showUsage) {
    var usageContent = usage.length
      ? usage.map(function (it) { return _renderItemCard(it, items.indexOf(it)); }).join("")
      : '<div class="_eli3_lr_results_empty"><div class="_eli3_lr_results_empty_icon">✅</div><div class="_eli3_lr_results_empty_desc">No usage risks detected.</div></div>';
    usageSectionHtml = _renderSection("usage", "Usage Risks", "⚙️", "#1d4ed8", usageContent, usage.length, usage.length === 0);
  }

  // ─── Section 3: Risk Rules Engine ────────────────────────────────
  // For each rule in the active library, compute:
  //   • matched — rule.agreementType matches the doc's agreement type
  //               (or rule has no agreementType = global)
  //   • fired   — at least one item's rule_applied references this rule
  //   • firedItems — those items, grouped under the rule
  // Rules are sorted: fired first (most impactful), then matched-but-
  // unfired (rules the AI considered but didn't flag), then unmatched
  // (rules from other agreement types — informational).
  function _ruleMatchesAgreement(rule) {
    if (!rule) return false;
    var ruleType = String(rule.agreementType || rule.type || "").toLowerCase().trim();
    if (!ruleType || ruleType === "all" || ruleType === "any") return true;
    if (!docType) return true; // unknown doc type — show as matched
    return ruleType === docType || ruleType.indexOf(docType) !== -1 || docType.indexOf(ruleType) !== -1;
  }
  function _itemFiredRule(item, rule) {
    var applied = String(item.rule_applied || "").trim().toLowerCase();
    if (!applied || applied === "n/a" || applied === "none") return false;
    var ruleName = String(rule.title || rule.name || rule.id || "").trim().toLowerCase();
    if (!ruleName) return false;
    return applied === ruleName || applied.indexOf(ruleName) !== -1 || ruleName.indexOf(applied) !== -1;
  }
  var rulesAnnotated = rulesList.map(function (rule) {
    var matched = _ruleMatchesAgreement(rule);
    var firedItems = items.filter(function (it) { return _itemFiredRule(it, rule); });
    return { rule: rule, matched: matched, fired: firedItems.length > 0, firedItems: firedItems };
  });
  // Sort: fired desc, matched desc, then alpha
  rulesAnnotated.sort(function (a, b) {
    if (a.fired !== b.fired) return a.fired ? -1 : 1;
    if (a.matched !== b.matched) return a.matched ? -1 : 1;
    return String(a.rule.title || a.rule.name || "").localeCompare(String(b.rule.title || b.rule.name || ""));
  });
  var firedCount = rulesAnnotated.filter(function (r) { return r.fired; }).length;
  var matchedCount = rulesAnnotated.filter(function (r) { return r.matched; }).length;
  var rulesEngineContent;
  if (!rulesList.length) {
    rulesEngineContent = '<div class="_eli3_lr_results_empty">' +
      '<div class="_eli3_lr_results_empty_icon">🛡️</div>' +
      '<div class="_eli3_lr_results_empty_desc">No Colgate rules installed. Add rules via <code>eli.dispatch("legal_risks","showRulesManager")</code>.</div>' +
    '</div>';
