      '<span class="_eli3_lr_rules_engine_chip _eli3_lr_rules_engine_chip_fired">' + firedCount + ' FIRED</span> ' +
      '<span class="_eli3_lr_rules_engine_chip _eli3_lr_rules_engine_chip_matched">' + matchedCount + ' MATCHED</span> ' +
      '<span class="_eli3_lr_rules_engine_chip _eli3_lr_rules_engine_chip_total">' + rulesList.length + ' total rules</span>' +
    '</div>';
    rulesEngineContent += rulesAnnotated.map(function (r) {
      var status = r.fired ? "FIRED" : (r.matched ? "MATCHED" : "UNRELATED");
      var statusCls = r.fired ? "_eli3_lr_rule_row_fired" :
                      (r.matched ? "_eli3_lr_rule_row_matched" : "_eli3_lr_rule_row_unmatched");
      var statusIcon = r.fired ? "✓" : (r.matched ? "•" : "—");
      var ruleType = r.rule.agreementType || r.rule.type || "any";
      var ruleName = r.rule.title || r.rule.name || r.rule.id || "(untitled)";
      var ruleDesc = r.rule.description || r.rule.detail || r.rule.rule || "";
      var firedCardsHtml = "";
      if (r.fired && r.firedItems.length) {
        firedCardsHtml = '<div class="_eli3_lr_rule_fired_items">' +
          r.firedItems.map(function (it) { return _renderItemCard(it, items.indexOf(it)); }).join("") +
