        '</div>';
    }).join("");
  }
  // 2026-05-13 update: hide the Risk Rules Engine section when 0 rules
  // match the agreement type. If the entire library is unrelated to
  // this doc, the section is noise (just a list of "—" rows). The
  // section IS shown when at least one rule matches (even if none
  // fired) — that's the "we checked your rules; none flagged anything"
  // signal, which is useful.
  var rulesEngineSectionHtml = "";
  if (rulesList.length && matchedCount > 0) {
    var rulesEngineSectionTitle = "Risk Rules Engine · " + firedCount + " of " + rulesList.length + " fired";
