    var arrow = root.querySelector("#_eli3_lr_overview_arrow");
    var hint = root.querySelector("#_eli3_lr_overview_hint");
    if (!body) return;
    var isHidden = body.hasAttribute("hidden");
    if (isHidden) {
      body.removeAttribute("hidden");
      arrow.textContent = "▼";
      hint.style.opacity = "0";
    } else {
      body.setAttribute("hidden", "");
      arrow.textContent = "◀";
      hint.style.opacity = "1";
    }
  };

  // Section collapse toggles — three sections (risks / usage / rules)
  // each share the same pattern: click head → toggle hidden + arrow.
  Array.prototype.forEach.call(root.querySelectorAll('[data-toggle^="section-"]'), function (head) {
    var key = head.getAttribute("data-toggle").replace("section-", "");
    head.onclick = function () {
      var body = root.querySelector("#_eli3_lr_section_body_" + key);
      var arrow = root.querySelector("#_eli3_lr_section_arrow_" + key);
