  overlay.appendChild(box);
  document.body.appendChild(overlay);

  var txtOrig         = box.querySelector("._eli3_lr_rw_orig");
  var txtInst         = box.querySelector("._eli3_lr_rw_inst");
  var btnRun          = box.querySelector("._eli3_lr_rw_run");
  var btnApplyAll     = box.querySelector("._eli3_lr_rw_apply_all");
  var btnFull         = box.querySelector("._eli3_lr_rw_full_replace");
  var btnCopy         = box.querySelector("._eli3_lr_rw_copy");
  var btnClose        = box.querySelector("._eli3_lr_rw_close");
  var lblSync         = box.querySelector("._eli3_lr_rw_sync_status");
