    var sourceText = txtOrig.value;
    var instr = txtInst.value;
    onRunAI(instr, sourceText, isMissing).then(function (aiText) {
      _aiResultText = String(aiText || "").trim();
      loadingState.setAttribute("hidden", "");
      _setRunning(false);
      btnFull.disabled = false;
      btnCopy.disabled = false;
      if (!isMissing && _syncedOriginalText) {
        _currentHunks = computeDiff(_syncedOriginalText, _aiResultText);
      } else {
        _currentHunks = [];
      }
      _paintPreview();
    }).catch(function (e) {
      loadingState.removeAttribute("hidden");
      loadingState.textContent = "❌ Error: " + (e && e.message || "unknown");
      _setRunning(false);
    });
  }

  // Render the redline preview body. ON: hunk diff with click-to-apply.
  // OFF: clean proposed text (what the apply will land in the doc).
  // Called by _runAI on completion AND by the toggle click.
  function _paintPreview() {
    if (isMissing && _aiResultText) {
      redlineBody.innerHTML = '<div class="_eli3_lr_rw_scratch">' + _esc(_aiResultText) + '</div>';
      hunkCountLbl.textContent = "";
      redlineSec.removeAttribute("hidden");
      btnApplyAll.disabled = true;
      return;
    }
    if (!_aiResultText || !_syncedOriginalText) return;
    var changeCount = (_currentHunks || []).filter(function (h) {
      return h.type === "change" || h.type === "insert" || h.type === "delete";
    }).length;
    if (changeCount === 0) {
      redlineBody.innerHTML = '<div class="_eli3_lr_rw_noop">✅ No differences detected — clause is already aligned.</div>';
      hunkCountLbl.textContent = "";
      redlineSec.removeAttribute("hidden");
      btnApplyAll.disabled = true;
      return;
    }
    redlineSec.removeAttribute("hidden");
    btnApplyAll.disabled = false;
    if (_redlinesOn) {
      // ON — diff view, per-hunk apply enabled.
      redlineBody.innerHTML = renderHunkHtml(_currentHunks);
      hunkCountLbl.textContent = changeCount + " change" + (changeCount > 1 ? "s" : "") + " detected";
      btnApplyAll.textContent = "✅ APPLY ALL " + changeCount + " CHANGES";
      _wireHunkClicks();
    } else {
      // OFF — show proposed text exactly as it will land in the doc.
      redlineBody.innerHTML = '<div class="_eli3_lr_rw_clean">' + _esc(_aiResultText) + '</div>';
      hunkCountLbl.textContent = "Clean replace · " + changeCount + " change" + (changeCount > 1 ? "s" : "");
      btnApplyAll.textContent = "📄 REPLACE CLAUSE";
    }
  }

  function _wireHunkClicks() {
    var els = redlineBody.querySelectorAll(".surgical-hunk");
    els.forEach(function (el) {
      el.onclick = function () {
        var idx = parseInt(el.getAttribute("data-hunk-id"), 10);
        var changeHunks = _currentHunks.filter(function (h) {
          return h.type === "change" || h.type === "insert" || h.type === "delete";
        });
        if (idx < 0 || idx >= changeHunks.length) return;
        var hunk = changeHunks[idx];
        el.style.opacity = "0.5";
        el.style.pointerEvents = "none";
        onApplyHunk(hunk, _currentHunks, _syncedOriginalText, _redlinesOn).then(function (res) {
          if (res && res.ok) {
            var newText = (hunk.newWords || []).join(" ");
            el.innerHTML = '<span class="_eli3_lr_rw_hunk_done">✅ ' + _esc(newText || "[deleted]") + '</span> ';
          } else {
            // Range not found — open hunk jumper for manual locate.
            el.style.opacity = "1";
            el.style.pointerEvents = "auto";
            onLocateAndApply(hunk, el, _syncedOriginalText);
          }
        }).catch(function () {
          el.style.opacity = "1";
          el.style.pointerEvents = "auto";
          onLocateAndApply(hunk, el, _syncedOriginalText);
        });
      };
    });
  }

  // Wire static buttons.
  btnRun.onclick = _runAI;
  btnApplyAll.onclick = function () {
    if (!_syncedOriginalText || !_aiResultText) return;
    var changeHunks = _currentHunks.filter(function (h) {
      return h.type === "change" || h.type === "insert" || h.type === "delete";
    });
    if (!changeHunks.length) return;
    btnApplyAll.disabled = true;
    btnApplyAll.textContent = _redlinesOn ? "⏳ Rebuilding Clause…" : "⏳ Replacing Clause…";
    onApplyAll(_syncedOriginalText, _aiResultText, _currentHunks, _redlinesOn).then(function (res) {
      if (res && res.ok) {
        btnApplyAll.textContent = _redlinesOn ? "✅ REBUILD COMPLETE" : "✅ REPLACED";
        btnApplyAll.classList.add("_eli3_lr_rw_apply_all_done");
        var els = redlineBody.querySelectorAll(".surgical-hunk");
        els.forEach(function (el, idx) {
          el.style.opacity = "0.5";
          el.style.pointerEvents = "none";
          var hunk = changeHunks[idx];
          if (hunk) {
            var n = (hunk.newWords || []).join(" ");
            el.innerHTML = '<span class="_eli3_lr_rw_hunk_done">✅ ' + _esc(n || "[deleted]") + '</span> ';
          }
        });
      } else {
        btnApplyAll.textContent = "❌ Rebuild Failed";
        btnApplyAll.disabled = false;
      }
    }).catch(function () {
      btnApplyAll.textContent = "❌ Rebuild Failed";
      btnApplyAll.disabled = false;
    });
  };
  btnFull.onclick = function () {
    if (!_aiResultText) return;
    onFullReplace(_aiResultText);
    _close();
  };
  btnCopy.onclick = function () {
    if (!_aiResultText) return;
    try { navigator.clipboard.writeText(_aiResultText); } catch (e) {}
    btnCopy.textContent = "✅ COPIED";
    setTimeout(function () { btnCopy.textContent = "📄 Copy"; }, 1500);
  };
  function _close() {
    if (overlay.parentNode) overlay.parentNode.removeChild(overlay);
    onClose();
  }
  btnClose.onclick = _close;

  // Initial selection sync — ask init for the cleaned text + status,
  // then auto-run AI. Mirrors v2's auto-sync-on-open behavior.
  onSyncSelection().then(function (sync) {
    sync = sync || {};
    if (sync.cleanText && sync.cleanText.length > 2) {
      txtOrig.value = sync.cleanText;
      _syncedOriginalText = sync.cleanText;
    }
    lblSync.textContent = sync.status || "✔️ Ready";
    if (sync.color) lblSync.style.color = sync.color;
    _runAI();
  }).catch(function () {
    lblSync.textContent = "⚠️ Sync error";
    _syncedOriginalText = txtOrig.value;
    _runAI();
  });

  return {
    overlay: overlay,
    close: _close,
  };
}

// renderHunkJumper — fallback bottom strip shown when applyHunk can't
// uniquely locate the old text. User selects the text manually, clicks
// Apply, init replaces the active selection. FROM v2 showHunkJumper
// (line 23333). All Word ops in init callbacks; view is pure DOM.

view.renderHunkJumper:
function renderHunkJumper(opts) {
  function _esc(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
  }
  opts = opts || {};
  var displayOld = String(opts.displayOldText || opts.oldText || "");
  var newText = String(opts.newText || "");
  var onSearch = opts.onSearch || function () { return Promise.resolve({ found: false }); };
  var onConfirm = opts.onConfirm || function () { return Promise.resolve({ ok: false }); };
  var onCancel = opts.onCancel || function () {};

  // Tear down prior jumper.
  var prior = document.getElementById("_eli3_lr_rw_jumper");
  if (prior && prior.parentNode) prior.parentNode.removeChild(prior);

  var jumper = document.createElement("div");
  jumper.id = "_eli3_lr_rw_jumper";
  jumper.className = "_eli3_lr_rw_jumper";

  var msg = document.createElement("div");
  msg.className = "_eli3_lr_rw_jumper_msg";
  msg.innerHTML = "🔍 Searching document…";

  var btnRow = document.createElement("div");
  btnRow.className = "_eli3_lr_rw_jumper_btns";
  var cancelBtn = document.createElement("button");
  cancelBtn.type = "button";
  cancelBtn.className = "_eli3_lr_rw_jumper_cancel";
  cancelBtn.textContent = "Skip / Cancel";
  var applyBtn = document.createElement("button");
  applyBtn.type = "button";
  applyBtn.className = "_eli3_lr_rw_jumper_apply";
  applyBtn.textContent = "⬇️ Apply Change";
  btnRow.appendChild(cancelBtn);
  btnRow.appendChild(applyBtn);

  jumper.appendChild(msg);
  jumper.appendChild(btnRow);
  document.body.appendChild(jumper);

  function _close() { if (jumper.parentNode) jumper.parentNode.removeChild(jumper); }

  // Run the search to seed the message + selection.
  onSearch().then(function (res) {
    if (res && res.found) {
      msg.innerHTML =
        '✅ Found &amp; selected. Confirm: ' +
        '<span class="_eli3_lr_rw_jumper_del">' + _esc(displayOld) + '</span> → ' +
        '<span class="_eli3_lr_rw_jumper_ins">' + _esc(newText || "[delete]") + '</span>';
      applyBtn.textContent = "✅ Confirm & Apply";
      applyBtn.classList.add("_eli3_lr_rw_jumper_apply_confirm");
    } else if (displayOld) {
      msg.innerHTML =
        '📌 Could not auto-locate. Highlight "<span class="_eli3_lr_rw_jumper_del">' + _esc(displayOld) +
        '</span>" in the document, then click Apply.';
    } else {
      msg.innerHTML =
        '📌 Place cursor where "<span class="_eli3_lr_rw_jumper_ins">' + _esc(newText) + '</span>" should go, then click Apply.';
    }
  }).catch(function () {
    if (displayOld) {
      msg.innerHTML =
        '📌 Highlight "<span class="_eli3_lr_rw_jumper_del">' + _esc(displayOld) +
        '</span>" in the document, then click Apply.';
    } else {
      msg.innerHTML = '📌 Place cursor in the document, then click Apply.';
    }
  });

  cancelBtn.onclick = function () { _close(); onCancel(); };
  applyBtn.onclick = function () {
    applyBtn.textContent = "⏳ Applying…";
    applyBtn.disabled = true;
    onConfirm().then(function (res) {
      _close();
      if (typeof opts.onAfterApply === "function") opts.onAfterApply(res && res.ok);
    }).catch(function () {
      applyBtn.textContent = "❌ Error - Try Again";
      applyBtn.disabled = false;
    });
  };

  return { jumper: jumper, close: _close };
}

jsonTools.init:
function init(eli) {
  if (!eli.events) eli.events = { guard: function (fn) { return fn; }, safeAsync: function (p) { return p; } };
  var bundle = eli.tools._loaded["legal_risks"];
  if (!bundle) return;

  // 2026-05-13 smile-loader: paints the SAME error_review-style overlay
  // every other tool uses. Self-contained — works regardless of kernel
  // version since each tool creates its own overlay div with the
  // shared `_eli3_er_progress_*` class names (CSS lives in error_review's
  // bundle; ensureLoaded keeps it present).
  function _lrShowSmile(message, onCancel) {
    if (eli.tools && typeof eli.tools.ensureLoaded === "function") {
      eli.tools.ensureLoaded("error_review").catch(function () {});
    }
    _lrHideSmile();
    try {
      var v2L = document.getElementById("loading");
      if (v2L) v2L.classList.add("hidden");
      var kernelOv = document.getElementById("_eli3_loading_overlay");
      if (kernelOv && kernelOv.parentNode) kernelOv.parentNode.removeChild(kernelOv);
    } catch (e) {}
    var ov = document.createElement("div");
    ov.id = "_eli3_lr_smile_overlay";
    ov.className = "_eli3_er_progress_overlay";
    var safeMsg = String(message || "Analyzing legal risks…").replace(/[<>&]/g, "");
    ov.innerHTML =
      '<div class="_eli3_er_progress_panel">' +
        '<div class="loading-card robot-loader" style="background:transparent;border:none;box-shadow:none;padding:10px 0;">' +
          '<div class="robot-head">' +
            '<div class="robot-eyes"><div class="robot-eye"></div><div class="robot-eye"></div></div>' +
            '<div class="mouth-container">' +
              '<div class="teeth-row upper">' +
                '<div class="tooth"></div><div class="tooth"></div><div class="tooth"></div>' +
                '<div class="tooth"></div><div class="tooth"></div><div class="tooth"></div>' +
                '<div class="tooth"></div>' +
              '</div>' +
              '<div class="teeth-row lower">' +
                '<div class="tooth"></div><div class="tooth"></div><div class="tooth"></div>' +
                '<div class="tooth"></div><div class="tooth"></div><div class="tooth"></div>' +
                '<div class="tooth"></div>' +
              '</div>' +
              '<div class="brush-anim">🪥</div>' +
              '<div class="foam f1"></div><div class="foam f2"></div><div class="foam f3"></div>' +
            '</div>' +
          '</div>' +
          '<p class="_eli3_er_progress_msg">' + safeMsg + '</p>' +
          (typeof onCancel === "function"
            ? '<button type="button" class="_eli3_loading_cancel" id="_eli3_lr_cancel_btn">Cancel</button>'
            : "") +
        '</div>' +
      '</div>';
    document.body.appendChild(ov);
    if (typeof onCancel === "function") {
      var cb = ov.querySelector("#_eli3_lr_cancel_btn");
      if (cb) cb.onclick = function () {
        try { onCancel(); } catch (e) {
          try { eli.log.event("tool", "legal_risks_cancel_threw", { msg: e && e.message }); } catch (_) {}
        }
      };
    }
  }
  function _lrHideSmile() {
    var ov = document.getElementById("_eli3_lr_smile_overlay");
    if (ov && ov.parentNode) ov.parentNode.removeChild(ov);
    // 2026-05-13 fix: keep v2 #loading HIDDEN (was removing the hidden
    // class, un-hiding the legacy progress bar = "second loader").
    try {
      var v2L = document.getElementById("loading");
      if (v2L) v2L.classList.add("hidden");
    } catch (e) {}
  }
  function _lrPaintSmileLoader(onCancel) { _lrShowSmile("Analyzing legal risks…", onCancel); }
  var efns = bundle._eliEngineFns || {};
  var vfns = bundle._eliViewFns || {};
  var analyze                  = efns.analyze;
  var renderSurgicalRedlineHtml = efns.renderSurgicalRedlineHtml;
  var computeWordDiffV2        = efns.computeWordDiffV2;
  var renderResults            = vfns.renderResults;
  var renderRewriteEditor      = vfns.renderRewriteEditor;
  var renderHunkJumper         = vfns.renderHunkJumper;
  if (!analyze || !renderResults) {
    eli.log.event("tool", "legal_risks_load_failed", {
      hasAnalyze: !!analyze, hasView: !!renderResults,
    });
    return;
  }

  // ─── Activity-entry tracking (FROM v2: showRewriteEditor lines
  // 23051-23060). When a scan completes we stash the activity entry's
  // id + total count so each FIX click can bump `_fixedCount` and
  // rewrite the summary as "N detected · M fixed".
  var _latestLegal360EntryId = null;
  var _latestLegal360Total   = 0;
  var _latestLegal360Fixed   = 0;
  function _bumpLegal360Fixed() {
    if (!_latestLegal360EntryId || !eli.activity || typeof eli.activity.update !== "function") return;
    _latestLegal360Fixed++;
    var summary = _latestLegal360Total + " detected · " + _latestLegal360Fixed + " fixed";
    try {
      eli.activity.update(_latestLegal360EntryId, {
        summary: summary,
        _fixedCount: _latestLegal360Fixed,
      });
    } catch (e) { /* tolerate */ }
  }

  // ─── Doc-hash helper (matches build_draft + ask_eli shape) ────────
  function _hashContent(text) {
    if (!text) return "empty";
    var s = String(text), hash = 0;
    for (var i = 0; i < s.length; i++) {
      hash = ((hash << 5) - hash) + s.charCodeAt(i);
      hash |= 0;
    }
    return "h" + (hash >>> 0).toString(36);
  }

  // ─── Load risk rules from IDB ─────────────────────────────────────
  // STORE_RISK_RULES = "risk_rules" — populated by risk_rules_manager
  // tool + the __data_risk_rules data bundle.
  function _loadRules() {
    if (!eli.storage || typeof eli.storage.getAll !== "function") return Promise.resolve([]);
    return eli.storage.getAll("risk_rules").then(function (rows) {
      return (rows || []).filter(function (r) {
        return r && r.id && String(r.id).charAt(0) !== "_";
      });
    }).catch(function () { return []; });
  }

  // ─── Read doc text (with stable per-paragraph anchors) ────────────
  // 2026-05-16: migrated from eli.host.readTextWithAnchors (deleted —
  // wrote per-tool ELI_LR_* bookmarks) to eli.host.helpers.getPromptAnchors
  // (returns the same [{id, text}] shape but ids reference the kernel's
  // shared ELI_IDX_* bookmarks via readStructuralMap). One bookmark set
  // per doc instead of two; restore survives goHome because the kernel
  // never sweeps ELI_IDX_*.
  function _readDocText() {
    var helpers = eli.host && eli.host.helpers;
    if (!helpers || typeof helpers.getPromptAnchors !== "function") {
      // Fallback — plain text read (kernel too old for the helper).
      if (eli.host && typeof eli.host.readText === "function") {
        return eli.host.readText().then(function (t) { return { text: t || "", anchors: [] }; });
      }
      return Promise.resolve({ text: "", anchors: [] });
    }
    return helpers.getPromptAnchors({ minLen: 5 }).then(function (anchors) {
      anchors = anchors || [];
      // Pass anchors as a JSON array of {id, text} — the prompt template
      // (data/prompts.json → legalRisksReview) tells the AI to return the
      // EXACT id property from the provided list (now "ELI_IDX_<n>").
      var text = JSON.stringify(anchors);
      return { text: text, anchors: anchors };
    }).catch(function () {
      return { text: "", anchors: [] };
    });
  }

  // ─── Locate a clause in the document ──────────────────────────────
  // LOCATE button handler. Single source of truth — the engine's
  // 2026-05-16: migrated to shared ELI_IDX_<n> anchors. Engine's
  // normalize step always sets item.id to "ELI_IDX_<n>" (or null if AI
  // didn't return one). Indexing happens at scan start via
  // eli.host.helpers.getPromptAnchors (wraps readStructuralMap); AI
  // gets [{id, text}] and returns the matching id. PRIMARY path: jump
  // to the bookmark via eli.host.highlightAnchor. Legacy ELI_LR_<n>
  // ids accepted on restore for backwards compat.
  //
  // 2026-05-16 fallback: bookmarks don't survive a doc close/reopen, so
  // RESTORED items from the activity feed always fail the bookmark
  // lookup. Fall back to text search (eli.host.helpers.searchWithFallback
  // — 4-strategy cascade) using the persisted item.text. Only used when
  // the bookmark path fails AND item.text is present; live scans still
  // hit the bookmark fast-path with zero search cost.
  function _locateClause(item) {
    var anchorId = String(item.id || "").trim();
    var clauseText = String(item.text || "").trim();
    var hasAnchor = anchorId && anchorId.indexOf("ELI_IDX_") === 0;
    if (!hasAnchor && !clauseText) {
      if (typeof showToast === "function") {
        showToast("No paragraph anchor or text for this clause — AI didn't return id (open Wrongness Viewer).", "warn");
      }
      return Promise.resolve(false);
    }
    if (!eli.host) {
      if (typeof showToast === "function") showToast("eli.host unavailable.", "err");
      return Promise.resolve(false);
    }
    // Primary: anchor highlight (fast path for live scans).
    function _tryAnchor() {
      if (!hasAnchor || typeof eli.host.highlightAnchor !== "function") {
        return Promise.resolve(false);
      }
      return eli.host.highlightAnchor(anchorId).then(function () { return true; }).catch(function () { return false; });
    }
    // Fallback: text search via the v2 helpers (cleanText + searchWithFallback).
    // Wraps in runRaw so we have a Word context; selects + scrolls to the
    // found range so it behaves like highlightAnchor.
    function _tryText() {
      if (!clauseText || !eli.host.runRaw || !eli.host.helpers || typeof eli.host.helpers.searchWithFallback !== "function") {
        return Promise.resolve(false);
      }
      return eli.host.runRaw("legal_risks:locate_text_fallback", function (ctx) {
        return eli.host.helpers.searchWithFallback(ctx.document.body, clauseText, item.context || "").then(function (range) {
          if (!range) return false;
          try { range.select(); } catch (_) {}
          try { range.scrollIntoView(); } catch (_) {}
          return ctx.sync().then(function () { return true; });
        });
      }).catch(function () { return false; });
    }
    return _tryAnchor().then(function (ok) {
      if (ok) return true;
      return _tryText().then(function (foundByText) {
        if (foundByText) {
          eli.log.event("tool", "legal_risks_locate_text_fallback_hit", { anchor: anchorId || null });
          return true;
        }
        if (typeof showToast === "function") {
          showToast(
            hasAnchor
              ? "Couldn't find this clause — anchor " + anchorId + " missing and text search came up empty. Re-run scan to refresh."
              : "Couldn't find this clause — text search came up empty.",
            "warn"
          );
        }
        eli.log.event("tool", "legal_risks_locate_failed", {
          anchor: anchorId || null,
          hadText: !!clauseText,
        });
        return false;
      });
    });
  }

  // ─── FIX button — surgical redline editor (v2 port) ──────────────
  // FROM v2 showRewriteEditor (taskpane_v2.js:23048). Opens the
  // interactive editor: original + AI instructions textareas, run AI
  // → live redline preview → click-to-apply per-hunk OR APPLY ALL.
  //
  // Heavy ops live in kernel:
  //   • Word diff:        eli.host.helpers.computeWordDiff
  //   • HTML render:      engine.renderSurgicalRedlineHtml
  //   • Surgical apply:   eli.host.applySurgicalRedline
  // Tool owns: AI call, selection sync, single-hunk apply, hunk jumper.
  function _fixClause(item) {
    var original = String(item.text || "").trim();
    var suggestion = String(item.fix_suggestion || "").trim();
    if (!original && !suggestion) {
      if (typeof showToast === "function") showToast("No clause text to fix.", "warn");
      return;
    }
    // FROM v2: bump risksMitigated stat + the legal-360 activity entry's
    // _fixedCount on every FIX open. Stat feeds gamification trophies;
    // activity bump rewrites the entry summary live ("N · M fixed").
    try { if (eli.stats && eli.stats.record) eli.stats.record("risksMitigated"); } catch (e) {}
    // Event-based: Midnight Oil (t153 — mitigate between 11 PM and 4 AM).
    try {
      if (eli.trophies && typeof eli.trophies.evaluate === "function") {
        eli.trophies.evaluate("risk_mitigated_late", {});
      }
    } catch (_) {}
    _bumpLegal360Fixed();
    // Suggestion may be instruction-style ("Rewrite to limit liability")
    // OR a literal replacement. Use the suggestion as the AI instruction
    // either way — AI re-generates the actual rewrite text on RUN.
    var instruction = suggestion ||
      "Rewrite this clause to be more favorable to Colgate-Palmolive, prioritizing our rights and limiting our liability.";
    if (!renderRewriteEditor) {
      // Editor view fn missing — fall back to legacy preview dialog.
      _legacyFixDialog(original, suggestion);
      return;
    }
    // Pass the paragraph anchor (e.g. "ELI_IDX_5") so all apply ops
    // resolve via bookmark first, text search as fallback.
    var anchorId = String(item.id || "").trim();
    if (anchorId.indexOf("ELI_IDX_") !== 0) anchorId = null;
    // 2026-05-16: redline-aware fix. If the target paragraph has pending
    // redlines, prompt the user to accept them in this section first so
    // the AI rewrites against clean text + a change-context summary.
    // No prompt + no change in behavior when the paragraph is clean.
    _maybeAcceptRedlinesFirst(anchorId, original, "Fix").then(function (pre) {
      if (!pre.proceed) return; // user declined the accept prompt
      var finalOriginal = pre.resolvedText || original;
      var finalInstruction = pre.changeContext
        ? pre.changeContext + "USER FIX INSTRUCTION: " + instruction
        : instruction;
      _openRewriteEditor(finalOriginal, finalInstruction, false, anchorId);
    }).catch(function () {
      // Detection failure → fall back to normal flow.
      _openRewriteEditor(original, instruction, false, anchorId);
    });
  }

  // ─── Redline-aware fix preflight (2026-05-16) ────────────────────
  // Checks the target paragraph for pending tracked changes. If found,
  // shows a consent dialog; on accept, accepts the redlines in-range
  // (scope-bounded — other paragraphs untouched) and returns the
  // resolved text + a change-context block to seed the AI prompt.
  // Returns { proceed, resolvedText?, changeContext? }. No-op + proceeds
  // unchanged when the paragraph has no redlines or kernel helpers are
