    var words = clean.split(/\s+/);
    if (words.length > 3) out.push(words.slice(0, Math.ceil(words.length * 0.8)).join(" "));
    if (words.length > 4) out.push(words.slice(0, Math.ceil(words.length / 2)).join(" "));
