        inserted.font.bold = false;
        inserted.font.italic = false;
        inserted.font.underline = "None";
        if (rangeToReplace.font.name) inserted.font.name = rangeToReplace.font.name;
        if (rangeToReplace.font.size) inserted.font.size = rangeToReplace.font.size;
      } else {
        if (rangeToReplace.font.name) inserted.font.name = rangeToReplace.font.name;
        if (rangeToReplace.font.size) inserted.font.size = rangeToReplace.font.size;
